#!/bin/sh
# Prints the Homebrew formula (Homebrew on Linux) for a release, with the
# tarball checksums taken from its checksums.txt.
#
# usage: homebrew-formula.sh VERSION CHECKSUMS_FILE
#
# Both binaries go to libexec and only companion is linked into bin: the core
# finds stt-sidecar next to os.Executable(), which on Linux is the resolved
# /proc/self/exe, so the bin symlink still leads it to libexec.
set -eu

version=${1:?usage: homebrew-formula.sh VERSION CHECKSUMS_FILE}
sums=${2:?usage: homebrew-formula.sh VERSION CHECKSUMS_FILE}
base="https://github.com/xlsft/companion/releases/download/v$version"

sha() {
	s=$(awk -v f="companion-$version-linux-$1.tar.gz" '$2 == f { print $1 }' "$sums")
	[ -n "$s" ] || { echo "homebrew-formula: no companion-$version-linux-$1.tar.gz in $sums" >&2; exit 1; }
	printf '%s' "$s"
}
x86=$(sha x86_64)
arm=$(sha aarch64)

cat <<EOF
# Generated by .github/scripts/homebrew-formula.sh in xlsft/companion for
# v$version; edits here are overwritten by the next release.
class Companion < Formula
  desc "Voice and screen assistant with local speech recognition"
  homepage "https://github.com/xlsft/companion"
  version "$version"
  license "FSL-1.1-ALv2"

  depends_on :linux

  on_intel do
    url "$base/companion-$version-linux-x86_64.tar.gz"
    sha256 "$x86"
  end
  on_arm do
    url "$base/companion-$version-linux-aarch64.tar.gz"
    sha256 "$arm"
  end

  def install
    # Must stay side by side: the core starts stt-sidecar from its own directory.
    libexec.install "companion", "stt-sidecar"
    bin.install_symlink libexec/"companion"
    share.install Dir["share/*"]
    prefix.install "LICENSE.md", "NOTICE", "licenses"
  end

  def caveats
    <<~EOS
      Companion uses the system graphics stack, PipeWire or PulseAudio and
      xdg-desktop-portal; see https://github.com/xlsft/companion/blob/main/docs/linux.md
      Run \`companion -diagnose\` to see what this desktop supports.
    EOS
  end

  test do
    assert_match version.to_s, shell_output("#{bin}/companion -version")
  end
end
EOF
